//! [`Catalog`]: the Rufus `.loc` locale catalog (S02).
//!
//! # File grammar (observed in `assets/resources/RCDATA_500.bin`)
//!
//! The file is UTF-8 with CRLF line endings, generated by "pollock v1.0".
//! There are **no** `msgid`/`msgstr` keywords and **no** `msgid_plural`
//! construct: every entry is one `t` line, and plural variants are simply
//! separate msgids with an explanatory comment. Representative lines:
//!
//! ```text
//! # • v4.14 "de-DE" "German (Deutsch)"
//! l "de-DE" "German (Deutsch)" 0x0407, 0x0807, 0x0c07, 0x1007, 0x1407
//! v 4.14
//! b "en-US"
//! g IDD_DIALOG
//! t IDS_DEVICE_TXT "Device"
//! t MSG_002 "Another Rufus application is running.\n"
//!     "Please close the first application before running another one."
//! # Number of bad block check passes (singular for 1 pass)
//! t MSG_034 "%d pass"
//! # Number of bad block check passes (plural for 2 or more passes).
//! t MSG_035 "%d passes %s"
//! t MSG_162 "Uncheck this box to use the \"slow\" format method"
//! ```
//!
//! Line kinds:
//!
//! * `#...` — comment (the header also lists all languages as
//!   `# • v<version> "<tag>" "<display name>"`).
//! * `l "<tag>" "<display>" <lcid>, ...` — starts a language block (38 in
//!   the real file, e.g. `en-US` … `vi-VN`); the LCID list is ignored.
//! * `v <version>` — catalog version marker, informational.
//! * `b "<tag>"` — base language of the block (always `en-US` outside the
//!   English block), informational: the fallback chain below implements it.
//! * `a "r"` — right-to-left marker (only `ar-SA`, `he-IL`, `fa-IR`),
//!   informational for now (a later GUI slice may use it for layout).
//! * `g <GROUP>` — dialog group marker (`IDD_DIALOG`, `IDD_ABOUTBOX`,
//!   `IDD_LICENSE`, `IDD_LOG`, `IDD_NEW_VERSION`, `IDD_NOTIFICATION`,
//!   `IDD_UPDATE_POLICY`), informational.
//! * `t <MSGID> "<text>"` — one entry; `<text>` may continue on following
//!   lines, each a single `"..."` segment. Segments concatenate directly
//!   (the `\n` escape inside the text provides the line break).
//!
//! String escapes are C-like. Observed in the wild: `\n`, `\"`, `\\`,
//! `\v`, `\t`. Also decoded: `\r`, `\a`, `\b`, `\f`, `\0`, `\'`, `\?`.
//! An unknown escape drops the backslash and keeps an ASCII character
//! as-is; a backslash before a non-ASCII byte is kept literally (the byte
//! sequence is preserved). Trailing characters after the closing quote,
//! unterminated strings, entries outside a language block, and unknown
//! statement lines are all errors — the parser never panics.
//!
//! # Lookup
//!
//! Tags are normalised (`de_DE.UTF-8` → `de-de`, underscores and case
//! ignored, `.suffix`/`@modifier` stripped) and resolved along the chain
//! `de-de` → `de` (first language sharing the primary subtag) → English
//! (the `en-US` block). [`Translator::t`] returns the msgid itself when
//! nothing is translated.
//!
//! # Performance
//!
//! Single pass over the bytes, one arena `String` for all translations plus
//! offset tables — no per-string `format!` on the hot path. The mapping
//! itself is confined to [`Catalog::from_path`]/[`from_bytes`]; a parsed
//! catalog owns plain Rust data (the memory map is dropped after parsing).

use std::collections::HashMap;
use std::fs;
use std::fs::File;
use std::path::Path;

use memmap2::MmapOptions;

use crate::error::CoreError;
use crate::error::Result;

/// Locale catalog: all translations of the `.loc` file, indexed by
/// (language, msgid).
#[derive(Debug, Default)]
pub struct Catalog {
    /// All unescaped translation texts, concatenated.
    arena: String,
    /// `(language index, msgid index)` → `(arena offset, byte length)`.
    /// First occurrence wins when a block repeats a msgid.
    entries: HashMap<(usize, usize), (usize, usize)>,
    /// Language tags in file order (`"en-US"`, ...).
    langs: Vec<String>,
    /// Normalised tag (`"de-de"`) → language index.
    lang_by_norm: HashMap<String, usize>,
    /// Primary subtag (`"de"`) → first language index with that primary.
    lang_by_primary: HashMap<String, usize>,
    /// Msgids in first-seen order.
    msgs: Vec<String>,
    /// Msgid → index.
    msg_by_name: HashMap<String, usize>,
}

impl Catalog {
    /// Parse the catalog from memory.
    pub fn from_bytes(data: &[u8]) -> Result<Self> {
        Self::parse(data, "<memory>")
    }

    /// Parse the catalog from a file.
    ///
    /// The file is memory-mapped with memmap2 when the platform can prove
    /// the mapping safe ([`MmapOptions::map_if_safe`], i.e. sealed memfds
    /// and fs-verity files on Linux); ordinary files cannot be proven
    /// immutable, so they take a plain-read fallback through the same
    /// single-pass parser. Either way the mapping (if any) is dropped
    /// before returning — the catalog owns its data.
    ///
    /// Rationale: memmap2 marks every file-backed constructor `unsafe`
    /// (a concurrent truncation could raise SIGBUS), and this crate forbids
    /// `unsafe_code`, so the safe API is attempted first and reading covers
    /// the rest. The 1.3 MB asset parses in a few milliseconds either way.
    pub fn from_path(path: &Path) -> Result<Self> {
        let label = path.display().to_string();
        let file = File::open(path).map_err(|err| CoreError::io(path, err))?;
        match MmapOptions::new().map_if_safe(&file) {
            Ok(mapping) => Self::parse(&mapping, &label),
            Err(err) if err.not_safe() || err.not_supported() => {
                let bytes = fs::read(path).map_err(|err| CoreError::io(path, err))?;
                Self::parse(&bytes, &label)
            }
            Err(err) => Err(CoreError::io(path, std::io::Error::from(err))),
        }
    }

    /// Language tags in file order.
    pub fn languages(&self) -> Vec<&str> {
        self.langs.iter().map(String::as_str).collect()
    }

    /// Translation for `msgid` in `lang`, following the fallback chain
    /// (full tag → primary subtag → English). Returns `None` when nothing
    /// is translated.
    pub fn get(&self, lang: &str, msgid: &str) -> Option<&str> {
        self.get_normalized(&normalize_locale(lang), msgid)
    }

    fn get_normalized(&self, norm: &str, msgid: &str) -> Option<&str> {
        if norm.is_empty() {
            return self.english(msgid);
        }
        if let Some(&index) = self.lang_by_norm.get(norm)
            && let Some(text) = self.lookup(index, msgid)
        {
            return Some(text);
        }
        if let Some(primary) = norm.split('-').next()
            && let Some(&index) = self.lang_by_primary.get(primary)
            && let Some(text) = self.lookup(index, msgid)
        {
            return Some(text);
        }
        self.english(msgid)
    }

    fn lookup(&self, lang: usize, msgid: &str) -> Option<&str> {
        let &msg = self.msg_by_name.get(msgid)?;
        let &(start, len) = self.entries.get(&(lang, msg))?;
        Some(&self.arena[start..start + len])
    }

    /// The `en-US` block (via the `"en"` primary, whatever English block
    /// the file lists first).
    fn english(&self, msgid: &str) -> Option<&str> {
        self.lang_by_primary
            .get("en")
            .and_then(|&index| self.lookup(index, msgid))
    }

    fn parse(data: &[u8], label: &str) -> Result<Self> {
        let text = std::str::from_utf8(data).map_err(|err| CoreError::LocaleParse {
            path: label.to_string(),
            line: 0,
            message: format!("not valid UTF-8 at byte {}", err.valid_up_to()),
        })?;
        let mut catalog = Self::default();
        let mut lines = text.split('\n').enumerate().peekable();
        let mut current: Option<usize> = None;
        while let Some((index, raw)) = lines.next() {
            let line_no = index as u64 + 1;
            let line = raw.strip_suffix('\r').unwrap_or(raw).trim_start();
            if line.is_empty() {
                continue;
            }
            match line.as_bytes()[0] {
                b'#' => {}
                b'l' => {
                    let rest = strip_keyword(line, "l").ok_or_else(|| {
                        CoreError::locale(label, line_no, format!("unknown statement {line}"))
                    })?;
                    current = Some(catalog.open_language(rest, label, line_no)?);
                }
                b'v' | b'b' | b'a' | b'g' => {
                    // Version/base/RTL/group markers are informational; only
                    // the statement shape is validated.
                    let keyword = &line[..1];
                    if strip_keyword(line, keyword).is_none() {
                        return Err(CoreError::locale(
                            label,
                            line_no,
                            format!("unknown statement {line}"),
                        ));
                    }
                }
                b't' => {
                    let rest = strip_keyword(line, "t").ok_or_else(|| {
                        CoreError::locale(label, line_no, format!("unknown statement {line}"))
                    })?;
                    let lang = current.ok_or_else(|| {
                        CoreError::locale(
                            label,
                            line_no,
                            "translation entry outside any language block".to_string(),
                        )
                    })?;
                    parse_entry(&mut catalog, lang, rest, label, line_no, &mut lines)?;
                }
                b'"' => {
                    return Err(CoreError::locale(
                        label,
                        line_no,
                        "continuation line without a translation entry".to_string(),
                    ));
                }
                _ => {
                    return Err(CoreError::locale(
                        label,
                        line_no,
                        format!("unknown statement {line}"),
                    ));
                }
            }
        }
        Ok(catalog)
    }

    /// Register an `l` line's language; returns its index.
    fn open_language(&mut self, rest: &str, label: &str, line_no: u64) -> Result<usize> {
        let rest = rest.trim_start();
        if !rest.starts_with('"') {
            return Err(CoreError::locale(
                label,
                line_no,
                "language block is missing its quoted tag".to_string(),
            ));
        }
        let end = rest[1..].find('"').ok_or_else(|| {
            CoreError::locale(label, line_no, "unterminated language tag".to_string())
        })?;
        let tag = &rest[1..1 + end];
        if tag.is_empty() {
            return Err(CoreError::locale(
                label,
                line_no,
                "empty language tag".to_string(),
            ));
        }
        let norm = normalize_locale(tag);
        if let Some(&index) = self.lang_by_norm.get(&norm) {
            return Ok(index);
        }
        let index = self.langs.len();
        self.langs.push(tag.to_string());
        self.lang_by_norm.insert(norm.clone(), index);
        if let Some(primary) = norm.split('-').next() {
            self.lang_by_primary
                .entry(primary.to_string())
                .or_insert(index);
        }
        Ok(index)
    }
}

/// `t <rest...>` with `lines` positioned after the `t` line: parse the
/// first segment, then consume continuation (`"..."`) lines.
fn parse_entry<'a, I>(
    catalog: &mut Catalog,
    lang: usize,
    rest: &str,
    label: &str,
    line_no: u64,
    lines: &mut std::iter::Peekable<I>,
) -> Result<()>
where
    I: Iterator<Item = (usize, &'a str)>,
{
    let rest = rest.trim_start();
    let (msgid, after) = match rest.find(|c: char| c.is_whitespace()) {
        Some(split) => (&rest[..split], rest[split..].trim_start()),
        None => (rest, ""),
    };
    if msgid.is_empty() || msgid.contains('"') {
        return Err(CoreError::locale(
            label,
            line_no,
            "translation entry is missing its msgid".to_string(),
        ));
    }
    if !after.starts_with('"') {
        return Err(CoreError::locale(
            label,
            line_no,
            format!("translation entry '{msgid}' is missing its opening quote"),
        ));
    }
    let msg = match catalog.msg_by_name.get(msgid) {
        Some(&index) => index,
        None => {
            let index = catalog.msgs.len();
            catalog.msgs.push(msgid.to_string());
            catalog.msg_by_name.insert(msgid.to_string(), index);
            index
        }
    };
    let start = catalog.arena.len();
    parse_segment(after, label, line_no, &mut catalog.arena)?;
    while let Some(&(index, raw)) = lines.peek() {
        let cont_no = index as u64 + 1;
        let cont = raw.strip_suffix('\r').unwrap_or(raw).trim_start();
        if !cont.starts_with('"') {
            break;
        }
        lines.next();
        parse_segment(cont, label, cont_no, &mut catalog.arena)?;
    }
    let len = catalog.arena.len() - start;
    catalog.entries.entry((lang, msg)).or_insert((start, len));
    Ok(())
}

/// Append one `"..."` segment (C-like escapes) to `out`.
///
/// `text` must start at the opening quote. Slicing only happens next to
/// ASCII bytes (`"`, `\`), which are always char boundaries, so this cannot
/// panic on multi-byte UTF-8.
fn parse_segment(text: &str, label: &str, line_no: u64, out: &mut String) -> Result<()> {
    let bytes = text.as_bytes();
    let mut pos = 1; // skip the opening quote
    let mut run = 1; // start of the pending verbatim run
    loop {
        if pos >= bytes.len() {
            return Err(CoreError::locale(
                label,
                line_no,
                "unterminated string".to_string(),
            ));
        }
        match bytes[pos] {
            b'"' => {
                out.push_str(&text[run..pos]);
                if text[pos + 1..].trim().is_empty() {
                    return Ok(());
                }
                return Err(CoreError::locale(
                    label,
                    line_no,
                    "trailing characters after string".to_string(),
                ));
            }
            b'\\' => {
                out.push_str(&text[run..pos]);
                pos += 1;
                if pos >= bytes.len() {
                    return Err(CoreError::locale(
                        label,
                        line_no,
                        "unterminated escape".to_string(),
                    ));
                }
                match bytes[pos] {
                    b'n' => out.push('\n'),
                    b't' => out.push('\t'),
                    b'v' => out.push('\x0B'),
                    b'r' => out.push('\r'),
                    b'a' => out.push('\x07'),
                    b'b' => out.push('\x08'),
                    b'f' => out.push('\x0C'),
                    b'0' => out.push('\0'),
                    other if other < 0x80 => out.push(char::from(other)),
                    // A backslash before a non-ASCII byte is kept
                    // literally; the byte sequence is preserved.
                    _ => {
                        out.push('\\');
                        run = pos;
                        continue;
                    }
                }
                pos += 1;
                run = pos;
            }
            _ => {
                pos += 1;
            }
        }
    }
}

/// `line == keyword` or starts with `"keyword "`, returning the remainder.
fn strip_keyword<'a>(line: &'a str, keyword: &str) -> Option<&'a str> {
    if line == keyword {
        return Some("");
    }
    line.strip_prefix(keyword)
        .and_then(|rest| rest.strip_prefix(' '))
}

/// `de_DE.UTF-8` → `de-de`; `de_DE` → `de-de`; ASCII case-insensitive.
/// Everything from the first `.`/`@` (encoding, modifier) is stripped.
fn normalize_locale(input: &str) -> String {
    let mut base = input;
    if let Some(cut) = input.find(['.', '@']) {
        base = &input[..cut];
    }
    let mut out = String::with_capacity(base.len());
    let mut first = true;
    for part in base.split(['-', '_']) {
        if !first {
            out.push('-');
        }
        first = false;
        out.push_str(&part.to_ascii_lowercase());
    }
    out
}

/// Bound translator: [`Catalog`] plus a normalised language tag.
pub struct Translator<'a> {
    catalog: &'a Catalog,
    lang: String,
}

impl<'a> Translator<'a> {
    /// Bind `catalog` to `lang` (normalised once, up front).
    pub fn new(catalog: &'a Catalog, lang: &str) -> Self {
        Self {
            catalog,
            lang: normalize_locale(lang),
        }
    }

    /// Normalised language tag in use.
    pub fn lang(&self) -> &str {
        &self.lang
    }

    /// Translate `msgid`, returning the msgid itself when untranslated
    /// (this is also the English fallback: the English block *is* the
    /// source language, so an untranslated id reads as English).
    pub fn t<'m>(&self, msgid: &'m str) -> &'m str
    where
        'a: 'm,
    {
        self.catalog
            .get_normalized(&self.lang, msgid)
            .unwrap_or(msgid)
    }
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;
    use std::time::Duration;
    use std::time::Instant;

    use super::*;

    fn asset_path() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../assets/resources/RCDATA_500.bin")
    }

    fn real_catalog() -> Catalog {
        let bytes = std::fs::read(asset_path()).expect("read real .loc asset");
        Catalog::from_bytes(&bytes).expect("parse real .loc asset")
    }

    #[test]
    fn parses_real_file_with_all_languages() {
        let catalog = real_catalog();
        let languages = catalog.languages();
        assert!(languages.len() >= 30, "{}", languages.len());
        assert!(languages.contains(&"en-US"));
        assert!(languages.contains(&"de-DE"));
        assert!(languages.contains(&"ar-SA"));
        assert_eq!(languages[0], "en-US", "file order preserved");
    }

    #[test]
    fn from_path_agrees_with_from_bytes() {
        let path = asset_path();
        let bytes = std::fs::read(&path).expect("read asset");
        let via_bytes = Catalog::from_bytes(&bytes).expect("from bytes");
        let via_path = Catalog::from_path(&path).expect("from path");
        assert_eq!(via_path.languages(), via_bytes.languages());
        assert_eq!(
            via_path.get("de-DE", "IDS_DEVICE_TXT"),
            via_bytes.get("de-DE", "IDS_DEVICE_TXT")
        );
        assert_eq!(
            via_path.get("fr-FR", "MSG_002"),
            via_bytes.get("fr-FR", "MSG_002")
        );
    }

    #[test]
    fn resolves_100_nonempty_translations_dynamically() {
        let catalog = real_catalog();
        let languages = catalog.languages();
        let other = languages
            .iter()
            .find(|lang| **lang != "en-US")
            .expect("non-English language");
        // Candidate msgids come from the catalog itself — nothing hardcoded.
        let found: Vec<(&str, &str)> = catalog
            .msgs
            .iter()
            .map(String::as_str)
            .filter_map(|msgid| {
                catalog
                    .get(other, msgid)
                    .filter(|text| !text.is_empty())
                    .map(|text| (msgid, text))
            })
            .take(100)
            .collect();
        assert_eq!(found.len(), 100, "language {other}");
        for (msgid, text) in found {
            assert!(!text.is_empty(), "{msgid}");
            assert_ne!(text, msgid, "{msgid} fell back to the id");
        }
    }

    #[test]
    fn missing_entries_fall_back_to_english() {
        let catalog = real_catalog();
        // Find a msgid the English block has but some language lacks, then
        // check the whole chain returns the English text for that language.
        let english: Vec<&str> = catalog.msgs.iter().map(String::as_str).collect();
        let mut checked = 0;
        for lang in catalog.languages() {
            if lang == "en-US" {
                continue;
            }
            for msgid in &english {
                let direct = catalog.lookup(catalog.lang_by_norm[&normalize_locale(lang)], msgid);
                if direct.is_none() {
                    let want = catalog.english(msgid).expect("english text");
                    assert_eq!(catalog.get(lang, msgid), Some(want), "{lang}/{msgid}");
                    checked += 1;
                    break;
                }
            }
            if checked >= 5 {
                break;
            }
        }
        assert!(checked >= 5, "expected gaps in some language");
    }

    #[test]
    fn locale_normalisation_and_chain() {
        let catalog = real_catalog();
        let plain = catalog.get("de-DE", "IDS_DEVICE_TXT").expect("de text");
        assert_eq!(catalog.get("de_DE", "IDS_DEVICE_TXT"), Some(plain));
        assert_eq!(catalog.get("de_DE.UTF-8", "IDS_DEVICE_TXT"), Some(plain));
        assert_eq!(catalog.get("DE-de", "IDS_DEVICE_TXT"), Some(plain));
        // Bare primary subtag resolves to the same block.
        assert_eq!(catalog.get("de", "IDS_DEVICE_TXT"), Some(plain));
        // Unknown locale → English text, not None.
        let english = catalog.get("en-US", "IDS_DEVICE_TXT").expect("en text");
        assert_eq!(catalog.get("xx-YY", "IDS_DEVICE_TXT"), Some(english));
        assert_eq!(catalog.get("", "IDS_DEVICE_TXT"), Some(english));
    }

    #[test]
    fn translator_returns_msgid_when_untranslated() {
        let catalog = real_catalog();
        let translator = Translator::new(&catalog, "de_DE.UTF-8");
        assert_eq!(translator.lang(), "de-de");
        assert_eq!(
            translator.t("THIS_MSGID_DOES_NOT_EXIST"),
            "THIS_MSGID_DOES_NOT_EXIST"
        );
        // ...and translated ids resolve.
        let direct = catalog.get("de-DE", "IDS_DEVICE_TXT").expect("de text");
        assert_eq!(translator.t("IDS_DEVICE_TXT"), direct);
    }

    #[test]
    fn continuations_concatenate_and_escapes_decode() {
        let catalog = Catalog::from_bytes(
            b"l \"en-US\" \"English\"\nt MSG_002 \"First.\\n\"\n\t\"Second \\\"quoted\\\" \\\\ done.\"\n",
        )
        .expect("parse");
        assert_eq!(
            catalog.get("en-US", "MSG_002"),
            Some("First.\nSecond \"quoted\" \\ done.")
        );
    }

    #[test]
    fn malformed_input_is_an_error_never_a_panic() {
        // Entry outside any language block.
        assert!(Catalog::from_bytes(b"t MSG_1 \"text\"\n").is_err());
        // Unterminated string.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\nt MSG_1 \"oops\n").is_err());
        // Unterminated escape.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\nt MSG_1 \"oops\\").is_err());
        // Missing opening quote.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\nt MSG_1 oops\n").is_err());
        // Trailing characters after the string.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\nt MSG_1 \"ok\" junk\n").is_err());
        // Stray continuation line.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\ng IDD_DIALOG\n\"stray\"\n").is_err());
        // Unknown statement.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\n? nonsense\n").is_err());
        // Unterminated language tag.
        assert!(Catalog::from_bytes(b"l \"en-US\n").is_err());
        // Invalid UTF-8.
        assert!(Catalog::from_bytes(b"l \"en-US\" \"E\"\nt MSG_1 \"\xff\"\n").is_err());
        // Invalid UTF-8 at the top level.
        assert!(Catalog::from_bytes(&[0xFF, 0xFE, b'\n']).is_err());
    }

    #[test]
    fn duplicate_msgid_keeps_first() {
        let catalog =
            Catalog::from_bytes(b"l \"en-US\" \"E\"\nt DUP \"first\"\nt DUP \"second\"\n")
                .expect("parse");
        assert_eq!(catalog.get("en-US", "DUP"), Some("first"));
    }

    #[test]
    fn missing_file_is_io_error() {
        let err = Catalog::from_path(Path::new("/no/such/dir/r.loc")).expect_err("must fail");
        assert!(err.to_string().contains("/no/such/dir/r.loc"));
    }

    #[test]
    fn loc_parse_timing() {
        let bytes = std::fs::read(asset_path()).expect("read real .loc asset");
        let mut durations = Vec::with_capacity(10);
        for _ in 0..10 {
            let started = Instant::now();
            let catalog = Catalog::from_bytes(&bytes).expect("parse");
            std::hint::black_box(catalog.languages());
            durations.push(started.elapsed());
        }
        durations.sort();
        let median = durations[durations.len() / 2];
        let min = durations[0];
        let max = durations[durations.len() - 1];
        eprintln!(
            "loc parse timing over 10 runs ({} bytes): min={min:?} median={median:?} max={max:?}",
            bytes.len()
        );
        for (index, elapsed) in durations.iter().enumerate() {
            eprintln!("  run {index}: {elapsed:?}");
        }
        if cfg!(debug_assertions) {
            eprintln!("debug build: 50 ms budget asserted in release only");
        } else {
            assert!(
                median < Duration::from_millis(50),
                "median parse {median:?} exceeds 50 ms budget"
            );
        }
    }
}
